#!/usr/bin/env python3
"""Хук Claude Code PreToolUse(Bash): тяжёлое мимо heavy.sh блокируется ТОЛЬКО когда хаб на пределе.

Тяжёлое: Unity с -batchmode/-buildTarget, duckpit/build/farm/build.sh, farm.sh, web-e2e,
google-chrome/chromium --headless, hub-make.sh. Пороги — как в heavy.sh v3:
HEAVY_CRIT_FREE_GB (12), HEAVY_CRIT_LOAD (4 × ядер), HEAVY_CRIT_MINE_GB (60).
Нормальные ресурсы или любая ошибка — exit 0 (никогда не ломать работу).
Отключить: HEAVY_HOOK_OFF=1 или файл .cache/heavy-hook.off в корне multicode.
"""
import json
import os
import re
import sys

ROOT = 'multicode'
HEAVY = [
    re.compile(r'(?:\bUnity\b|editor\.sh|unity\.sh)[^\n;&|]*?(?:-batchmode|-buildTarget)'),
    re.compile(r'build/farm/build\.sh'),
    re.compile(r'(?:^|[\s/;&|(])farm\.sh\b'),
    re.compile(r'web-e2e'),
    re.compile(r'(?:google-chrome\S*|chromium\S*|chrome-headless-shell)[^\n;&|]*?--headless'),
    re.compile(r'hub-make\.sh'),
]


def env_num(name, default):
    try:
        return float(os.environ[name])
    except (KeyError​, ValueError):
        return default


def crit():
    free_gb = env_num('HEAVY_CRIT_FREE_GB', 12)
    max_load = env_num('HEAVY_CRIT_LOAD', 4 * (os.cpu_count() or 1))
    mine_gb = env_num('HEAVY_CRIT_MINE_GB', 60)
    with open('/proc/meminfo') as f:
        for line in f:
            if line.startswith('MemAvailable:'):
                avail = int(line.split()[1]) / 1048576
                break
    if avail < free_gb:
        return 'свободно %d ГБ < %g' % (avail, free_gb)
    with open('/proc/loadavg') as f:
        load = float(f.read().split()[0])
    if load > max_load:
        return 'load %.0f > %g' % (load, max_load)
    uid, page, rss = os.getuid(), os.sysconf('SC_PAGE_SIZE'), 0
    for pid in os.listdir('/proc'):
        if not pid.isdigit():
            continue
        try:
            if os.stat('/proc/' + pid).st_uid != uid:
                continue
            with open('/proc/%s/statm' % pid) as f:
                rss += int(f.read().split()[1]) * page
        except (OSError, ValueError, IndexError):
            pass
    if rss / 2**30 > mine_gb:
        return 'у нас уже %d ГБ > %g' % (rss / 2**30, mine_gb)
    return ''


def main():
    if os.environ.get('HEAVY_HOOK_OFF') == '1' or os.path.exists(ROOT + '/.cache/heavy-hook.off'):
        return 0
    data = json.load(sys.stdin)
    if data.get('tool_name', 'Bash') != 'Bash':
        return 0
    cmd = (data.get('tool_input') or {}).get('command') or ''
    if not isinstance(cmd, str) or 'heavy.sh' in cmd:
        return 0
    if not any(r.search(cmd) for r in HEAVY):
        return 0
    reason = crit()
    if not reason:
        return 0
    sys.stderr.write('Хаб на пределе (%s). Запусти через tools/scripts/heavy.sh <команда> — '
                     'он подождёт, пока освободится.\n' % reason)
    return 2


if __name__ == '__main__':
    try:
        code = main()
    except Exception:
        code = 0
    sys.exit(code)
EOF
